  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
}
.skip-link:focus {
  top: 8px;
}

/* Layout */
.page-wrapper {
  min-height: 100vh;
