(function () {
  'use strict';

  const QUESTIONS = [
    {
      id: 'q1',
      text: 'Which of the following are statically typed languages?',
      help: 'Select all that apply. There may be more than one correct answer.',
      options: [
        { value: 'typescript', label: 'TypeScript' },
        { value: 'rust',       label: 'Rust' },
        { value: 'python',     label: 'Python' },
        { value: 'javascript', label: 'JavaScript' },
      ],
      correct: new Set(['typescript', 'rust']),
    },
    {
      id: 'q2',
      text: 'Which languages are primarily used for systems programming?',
      options: [
        { value: 'c',      label: 'C' },
        { value: 'ruby',   label: 'Ruby' },
        { value: 'cpp',    label: 'C++' },
        { value: 'kotlin', label: 'Kotlin' },
      ],
      correct: new Set(['c', 'cpp']),
    },
    {
      id: 'q3',
      text: 'Which of the following languages compile to bytecode that runs on a virtual machine?',
      options: [
        { value: 'java',   label: 'Java' },
        { value: 'go',     label: 'Go' },
        { value: 'csharp', label: 'C#' },
        { value: 'php',    label: 'PHP' },
      ],
      correct: new Set(['java', 'csharp']),
    },
  ];

  const form = document.getElementById('quiz-form');
  const progressFill = document.getElementById('progress-fill');
  const progressLabel = document.getElementById('progress-label');
  const resultBanner = document.getElementById('result-banner');
  const resultIcon = document.getElementById('result-icon');
  const resultHeading = document.getElementById('result-heading');
  const resultDetail = document.getElementById('result-detail');

  /* ---------- Progress ---------- */
  function updateProgress() {
    const answered = QUESTIONS.filter(q => getSelected(q.id).length > 0).length;
    const pct = Math.round((answered / QUESTIONS.length) * 100);
    progressFill.style.width = pct + '%';
    progressLabel.textContent = answered + ' / ' + QUESTIONS.length + ' answered';
  }

  function getSelected(questionId) {
    return Array.from(
      form.querySelectorAll(`input[name="${questionId}"]:checked`)
    ).map(el => el.value);
  }

  /* ---------- Attach change listeners ---------- */
  QUESTIONS.forEach(q => {
    const checkboxes = form.querySelectorAll(`input[name="${q.id}"]`);
    checkboxes.forEach(cb => {
      cb.addEventListener('change', () => {
        // Clear validation error once user interacts
        const field = document.getElementById('field-' + q.id);
        if (field) field.classList.remove('has-error');
        updateProgress();
      });
    });
  });

  /* ---------- Validate ---------- */
  function validate() {
    let firstInvalidField = null;
    let valid = true;

    QUESTIONS.forEach(q => {
      const field = document.getElementById('field-' + q.id);
      const selected = getSelected(q.id);
      if (selected.length === 0) {
        field.classList.add('has-error');
        valid = false;
        if (!firstInvalidField) firstInvalidField = field;
      }
    });

    if (!valid && firstInvalidField) {
      // Focus the first unchecked checkbox in that fieldset
      const firstCb = firstInvalidField.querySelector('input[type="checkbox"]');
      if (firstCb) firstCb.focus();
    }

    return valid;
  }

  /* ---------- Score ---------- */
  function scoreQuestion(q) {
    const selected = new Set(getSelected(q.id));
    const correct = q.correct;
    // Must select exactly the correct set
    if (selected.size !== correct.size) return false;
    for (const v of selected) {
      if (!correct.has(v)) return false;
    }
    return true;
  }

  function showFeedback() {
    let score = 0;
    QUESTIONS.forEach(q => {
      const isCorrect = scoreQuestion(q);
      if (isCorrect) score++;

      const feedback = document.getElementById('feedback-' + q.id);
      if (!feedback) return;

      const correctLabels = q.options
        .filter(o => q.correct.has(o.value))
        .map(o => o.label)
        .join(', ');

      if (isCorrect) {
        feedback.className = 'answer-feedback correct';
        feedback.textContent = '✓ Correct!';
      } else {
        feedback.className = 'answer-feedback incorrect';
        feedback.textContent = `✗ Not quite. Correct answer(s): ${correctLabels}.`;
      }
    });
    return score;
  }

  function showResult(score) {
    resultBanner.classList.remove('success', 'partial', 'fail');
    const total = QUESTIONS.length;

    if (score === total) {
      resultBanner.classList.add('success');
      resultIcon.textContent = '🎉';
      resultHeading.textContent = 'Perfect score!';
      resultDetail.textContent = `You got all ${total} questions right. Impressive command of computer languages!`;
    } else if (score >= 1) {
      resultBanner.classList.add('partial');
      resultIcon.textContent = '📚';
      resultHeading.textContent = `${score} out of ${total} correct`;
      resultDetail.textContent = 'Good effort! Review the questions below to see where you went wrong.';
    } else {
      resultBanner.classList.add('fail');
      resultIcon.textContent = '💡';
      resultHeading.textContent = 'Keep learning!';
      resultDetail.textContent = 'You got 0 out of ' + total + '. Review the answers below and try again.';
    }

    resultBanner.classList.add('show');
    resultBanner.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    // Announce to screen readers
    resultBanner.setAttribute('aria-live', 'polite');
  }

  /* ---------- Submit ---------- */
  form.addEventListener('submit', function (e) {
    e.preventDefault();

    if (!validate()) return;

    const score = showFeedback();
    showResult(score);

    // Disable further interaction
    form.classList.add('quiz-submitted');
  });
})();

