  --color-primary-active: #2c44cc;
  --color-text: #1a1d2e;
  --color-text-muted: #6b7280;
  --color-help: #4b5563;
  --color-success-bg: #ecfdf5;
  --color-success-border: #6ee7b7;
  --color-success-text: #065f46;
  --color-error-bg: #fef2f2;
  --color-error-border: #fca5a5;
  --color-error-text: #991b1b;
  --color-check-bg: #4f6ef7;
  --color-check-border: #4f6ef7;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-card: 0 2px 16px 0 rgba(79, 110, 247, 0.08), 0 1px 4px 0 rgba(26, 29, 46, 0.06);
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
}

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  line-height: 1.6;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -999px;
  left: 8px;
  background: var(--color-primary);
  color: #fff;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
}
.skip-link:focus {
  top: 8px;
}

/* Layout */
.page-wrapper {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 48px 16px 64px;
}

.quiz-card {
  width: 100%;
  max-width: 640px;
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 40px 40px 36px;
}

/* Header */
.quiz-header {
  margin-bottom: 36px;
}

.quiz-label {
  display: inline-block;
  background: #eef1ff;
  color: var(--color-primary);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 99px;
  margin-bottom: 12px;
}

.quiz-title {
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--color-text);
  line-height: 1.25;
  margin-bottom: 8px;
}

.quiz-subtitle {
  font-size: 0.9375rem;
  color: var(--color-text-muted);
}

/* Progress */
.quiz-progress {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 32px;
}

.progress-bar-track {
  flex: 1;
  height: 6px;
  background: #e5e7ef;
  border-radius: 99px;
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  background: var(--color-primary);
  border-radius: 99px;
  width: 0%;
  transition: width 0.4s ease;
}

.progress-label {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-text-muted);
  white-space: nowrap;
}

/* Divider */
.divider {
  border: none;
  border-top: 1px solid var(--color-border);
  margin-bottom: 32px;
}

/* Form field wrapper */
.form-field {
  margin-bottom: 32px;
}

.form-field:last-of-type {
  margin-bottom: 0;
}

/* Fieldset & legend */
.form-field fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

.question-number {
  display: block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--color-primary);
  text-transform: uppercase;
  margin-bottom: 4px;
}

.form-field legend {
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.4;
  margin-bottom: 6px;
  float: left;
  width: 100%;
}

/* Help text */
.help-text {
  display: block;
  font-size: 0.8125rem;
  color: var(--color-help);
  margin-bottom: 14px;
  clear: both;
}

/* Checkbox options */
.checkbox-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
  clear: both;
}

.checkbox-option {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s, box-shadow 0.15s;
  user-select: none;
  position: relative;
}

.checkbox-option:hover {
  border-color: var(--color-primary);
  background: #f5f7ff;
}

.checkbox-option input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  min-width: 20px;
  border: 2px solid var(--color-border);
  border-radius: 5px;
  background: #fff;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
  position: relative;
  display: grid;
  place-items: center;
}

.checkbox-option input[type="checkbox"]::after {
  content: '';
  display: block;
  width: 5px;
  height: 9px;
  border: 2.5px solid transparent;
  border-left: none;
  border-top: none;
  transform: rotate(45deg) translate(-1px, -1px);
  transition: border-color 0.1s;
}

.checkbox-option input[type="checkbox"]:checked {
  background: var(--color-check-bg);
  border-color: var(--color-check-border);
}

.checkbox-option input[type="checkbox"]:checked::after {
  border-color: #fff;
}

/* Focus */
.checkbox-option input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

.checkbox-option:has(input:checked) {
  border-color: var(--color-primary);
  background: #f0f3ff;
}

.checkbox-option-label {
  font-size: 0.9375rem;
  color: var(--color-text);
  line-height: 1.45;
  cursor: pointer;
}

/* Validation error message */
.field-error {
  display: none;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
  font-size: 0.8125rem;
  font-weight: 600;
  color: #b91c1c;
}

.field-error svg {
  flex-shrink: 0;
}

.form-field.has-error .field-error {
  display: flex;
}

.form-field.has-error .checkbox-group {
  border-radius: var(--radius-md);
  outline: 2px solid #f87171;
  outline-offset: 2px;
}

/* Submit area */
.form-actions {
  margin-top: 36px;
  padding-top: 28px;
  border-top: 1px solid var(--color-border);
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--color-primary);
  color: #fff;
  border: none;
  border-radius: var(--radius-md);
  padding: 13px 28px;
  font-size: 0.9375rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  box-shadow: 0 2px 8px rgba(79, 110, 247, 0.28);
  letter-spacing: 0.01em;
}

.btn-submit:hover {
  background: var(--color-primary-hover);
  box-shadow: 0 4px 14px rgba(79, 110, 247, 0.38);
}

.btn-submit:active {
  background: var(--color-primary-active);
  transform: translateY(1px);
  box-shadow: 0 1px 4px rgba(79, 110, 247, 0.2);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* Result banner */
.result-banner {
  display: none;
  align-items: flex-start;
  gap: 14px;
  padding: 18px 20px;
  border-radius: var(--radius-md);
  margin-top: 24px;
  font-size: 0.9375rem;
  line-height: 1.5;
}

.result-banner.show {
  display: flex;
}

.result-banner.success {
  background: var(--color-success-bg);
  border: 1.5px solid var(--color-success-border);
  color: var(--color-success-text);
}

.result-banner.partial {
  background: #fffbeb;
  border: 1.5px solid #fcd34d;
  color: #92400e;
}

.result-banner.fail {
  background: var(--color-error-bg);
  border: 1.5px solid var(--color-error-border);
  color: var(--color-error-text);
}

.result-icon {
  font-size: 1.4rem;
  line-height: 1;
  flex-shrink: 0;
}

.result-text strong {
  display: block;
  font-size: 1rem;
  font-weight: 800;
  margin-bottom: 2px;
}

/* Question result feedback */
.answer-feedback {
  display: none;
  margin-top: 10px;
  font-size: 0.8125rem;
  font-weight: 600;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
}

.answer-feedback.correct {
  display: block;
  background: #ecfdf5;
  color: #065f46;
}

.answer-feedback.incorrect {
  display: block;
  background: #fef2f2;
  color: #991b1b;
}

/* Disabled state after submit */
.quiz-submitted .checkbox-option {
  cursor: default;
  pointer-events: none;
}

.quiz-submitted .btn-submit {
  opacity: 0.6;
  cursor: not-allowed;
  pointer-events: none;
}

/* Responsive */
@media (max-width: 520px) {
  .quiz-card {
    padding: 28px 20px 24px;
    border-radius: var(--radius-md);
  }

  .quiz-title {
    font-size: 1.3rem;
  }
}

/* Forced colors */
@media (forced-colors: active) {
  .checkbox-option input[type="checkbox"]:checked {
    background: ButtonText;
    border-color: ButtonBorder;
  }
  .checkbox-option input[type="checkbox"]:checked::after {
    border-color: ButtonFace;
  }
  .btn-submit {
    border: 2px solid ButtonBorder;
  }
}
